import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

// Cache the result of getPosts() for 1 hour (the "hours" cacheLife profile
// revalidates every 3600 seconds) and tag it with "posts" so it can be
// invalidated on-demand via revalidateTag('posts').
async function getCachedPosts() {
  'use cache'
  cacheLife('hours')
  cacheTag('posts')
  return getPosts()
}

export default async function Home() {
  const posts = await getCachedPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

